                  terraUnits: typeof s.diagnostic.common.terraUnits === 'number' ? s.diagnostic.common.terraUnits : null,
                  terraUnitsPresent: s.diagnostic.common.terraUnits !== undefined,
                  routeUnitsRequired: ${CG_COMMON_ROUTE_UNITS},
