  const tick = (rafTimeMs) => {
    if (state.sealed) return;
    try { push(sample(rafTimeMs)); state.frames += 1; }
    catch (e) { state.sampleErrors += 1; state.lastError = String(e && e.stack ? e.stack : e).slice(0, 300); }
