    handle = cfg.driver === 'timer' ? setTimeout(() => tick(null), cfg.timerMs || 8) : requestAnimationFrame(tick);
  };

  window.__finaleWindowProbe = {
    installed: true,
    schema: ${JSON.stringify(SAMPLER_SCHEMA)},
    cfg,
    inventory,
